+package sprint
+
+import (
+	"crypto/sha256"
+	"encoding/hex"
+	"encoding/json"
+	"fmt"
+	"path/filepath"
+	"regexp"
+	"sort"
+	"strings"
+
+	pprocess "github.com/Antonio7098/ultraplan-go/internal/platform/process"
+)
+
+const PerformanceRunnerVersion = "performance-runner-v1"
+
+var goBenchmarkSymbol = regexp.MustCompile(`^Benchmark[A-Za-z0-9_]+$`)
+var jsonPerformanceSymbol = regexp.MustCompile(`^Test[A-Za-z0-9_]+$`)
+var packageLocator = regexp.MustCompile(`^(?:\.|[A-Za-z0-9_][A-Za-z0-9_.-]*)(?:/[A-Za-z0-9_][A-Za-z0-9_.-]*)*$`)
+
+func ValidatePerformanceManifest(packet PerformanceTargetPacket, manifest *PerformanceBenchmarkManifest) error {
+	if manifest == nil {
+		return fmt.Errorf("benchmark manifest is required")
+	}
+	if manifest.SchemaVersion != PerformanceSchemaVersion || manifest.PacketDigest != packet.PacketDigest || manifest.RunnerVersion != PerformanceRunnerVersion || manifest.ParserVersion != PerformanceParserVersion {
+		return fmt.Errorf("benchmark manifest identity does not match the frozen target packet")
+	}
+	targets := make(map[string]PerformanceTarget, len(packet.Targets))
+	for _, target := range packet.Targets {
+		targets[target.ID] = target
+	}
+	covered := map[string]bool{}
+	outputs := map[string]bool{}
+	for i := range manifest.Descriptors {
+		descriptor := &manifest.Descriptors[i]
+		if err := ValidatePerformanceDescriptor(*descriptor); err != nil {
+			return fmt.Errorf("descriptor %d: %w", i+1, err)
+		}
+		if outputs[descriptor.OutputIdentity] {
+			return fmt.Errorf("duplicate output identity %q", descriptor.OutputIdentity)
+		}
+		outputs[descriptor.OutputIdentity] = true
+		for _, id := range descriptor.TargetIDs {
+			target, ok := targets[id]
+			if !ok {
+				return fmt.Errorf("descriptor maps unknown target %q", id)
+			}
+			if covered[id] {
+				return fmt.Errorf("target %q has duplicate benchmark coverage", id)
+			}
+			if target.Basis != PerformanceRelative && descriptor.RawUnit != target.Unit {
+				return fmt.Errorf("target %q raw unit %q does not match %q", id, descriptor.RawUnit, target.Unit)
+			}
+			if target.Basis == PerformanceRelative && descriptor.RawUnit == PerformancePercent {
+				return fmt.Errorf("target %q baseline comparison requires a non-percent raw unit", id)
+			}
+			covered[id] = true
+		}
+	}
+	if len(covered) != len(targets) {
+		return fmt.Errorf("benchmark coverage is incomplete: covered %d of %d targets", len(covered), len(targets))
+	}
+	manifest.CoverageComplete = true
+	wantDigest := performanceManifestDigest(*manifest)
+	if manifest.BenchmarkDigest != "" && manifest.BenchmarkDigest != wantDigest {
+		return fmt.Errorf("benchmark manifest digest does not match its frozen descriptors")
+	}
+	manifest.BenchmarkDigest = wantDigest
+	return nil
+}
+
+func ValidatePerformanceDescriptor(descriptor PerformanceDescriptor) error {
+	if descriptor.Kind != PerformanceGoBenchmark && descriptor.Kind != PerformanceJSONRunner {
+		return fmt.Errorf("unsupported descriptor kind %q", descriptor.Kind)
+	}
+	if !packageLocator.MatchString(descriptor.Package) || filepath.IsAbs(descriptor.Package) || strings.Contains(descriptor.Package, "..") {
+		return fmt.Errorf("unsafe package locator %q", descriptor.Package)
+	}
+	if descriptor.Kind == PerformanceGoBenchmark && !goBenchmarkSymbol.MatchString(descriptor.Symbol) {
+		return fmt.Errorf("invalid Go benchmark symbol %q", descriptor.Symbol)
+	}
+	if descriptor.Kind == PerformanceJSONRunner && !jsonPerformanceSymbol.MatchString(descriptor.Symbol) {
+		return fmt.Errorf("invalid JSON runner symbol %q", descriptor.Symbol)
+	}
+	if len(descriptor.TargetIDs) == 0 || len(descriptor.TargetIDs) > PerformanceMaxTargets || !supportedPerformanceUnit(descriptor.RawUnit) || descriptor.RawUnit == PerformancePercent {
+		return fmt.Errorf("descriptor target mapping or raw unit is invalid")
+	}
+	if descriptor.ParserVersion != PerformanceParserVersion {
+		return fmt.Errorf("unsupported parser version %q", descriptor.ParserVersion)
+	}
+	wantOutput := string(descriptor.Kind) + ":" + descriptor.Package + ":" + descriptor.Symbol + ":" + string(descriptor.RawUnit)
+	if descriptor.OutputIdentity != wantOutput {
+		return fmt.Errorf("output identity must be %q", wantOutput)
+	}
+	sorted := append([]string(nil), descriptor.TargetIDs...)
+	sort.Strings(sorted)
+	for i, id := range sorted {
+		if !performanceTargetID.MatchString(id) || i > 0 && id == sorted[i-1] {
+			return fmt.Errorf("invalid or duplicate target ID %q", id)
+		}
+	}
+	descriptor.TargetIDs = sorted
+	return nil
+}
+
+func PerformanceProcessRequest(root string, descriptor PerformanceDescriptor, limits PerformanceLimits, env []string) (pprocess.Request, error) {
+	if err := ValidatePerformanceDescriptor(descriptor); err != nil {
+		return pprocess.Request{}, err
+	}
+	if limits.CommandTimeout <= 0 || limits.StdoutBytes <= 0 || limits.StderrBytes <= 0 || limits.CleanupReserve <= 0 {
+		return pprocess.Request{}, fmt.Errorf("performance process limits must be positive")
+	}
+	cleanRoot := filepath.Clean(root)
+	args := []string{"test", descriptor.Package, "-count=1"}
+	if descriptor.Kind == PerformanceGoBenchmark {
+		args = append(args, "-run=^$", "-bench=^"+descriptor.Symbol+"$", "-benchmem")
+	} else {
+		args = append(args, "-run=^"+descriptor.Symbol+"$", "-v")
+	}
+	return pprocess.Request{Executable: "go", Args: args, Dir: cleanRoot, Env: allowPerformanceEnvironment(env), Timeout: limits.CommandTimeout, StdoutLimit: limits.StdoutBytes, StderrLimit: limits.StderrBytes, CleanupGrace: limits.CleanupReserve}, nil
+}
+
+func PerformanceProfileRequest(root, output string, descriptor PerformanceDescriptor, kind PerformanceProfileKind, limits PerformanceLimits, env []string) (pprocess.Request, error) {
+	request, err := PerformanceProcessRequest(root, descriptor, limits, env)
+	if err != nil {
+		return request, err
+	}
+	if output == "" || !filepath.IsAbs(output) {
+		return request, fmt.Errorf("performance profile output must be absolute")
+	}
+	switch kind {
+	case PerformanceProfileCPU:
+		if descriptor.Kind != PerformanceGoBenchmark {
+			return request, fmt.Errorf("CPU profile requires a Go benchmark descriptor")
+		}
+		request.Args = append(request.Args, "-cpuprofile="+output)
+	case PerformanceProfileAllocation:
+		if descriptor.Kind != PerformanceGoBenchmark {
+			return request, fmt.Errorf("allocation profile requires a Go benchmark descriptor")
+		}
+		request.Args = append(request.Args, "-memprofile="+output, "-memprofilerate=1")
+	case PerformanceProfileMemory, PerformanceProfileWall, PerformanceProfileThroughput, PerformanceProfileCount:
+		// The closed JSON runner output is itself the bounded source profile.
+	default:
+		return request, fmt.Errorf("unsupported performance profile kind %q", kind)
+	}
+	return request, nil
+}
+
+func allowPerformanceEnvironment(env []string) []string {
+	allowed := map[string]bool{"PATH": true, "HOME": true, "TMPDIR": true, "LANG": true, "LC_ALL": true, "GOCACHE": true, "GOMODCACHE": true, "GOMAXPROCS": true}
+	result := make([]string, 0, len(env))
+	for _, entry := range env {
+		key := entry
+		if at := strings.IndexByte(entry, '='); at >= 0 {
+			key = entry[:at]
+		}
+		if allowed[key] {
+			result = append(result, entry)
+		}
+	}
+	sort.Strings(result)
+	return result
+}
+
+func performanceManifestDigest(manifest PerformanceBenchmarkManifest) string {
+	manifest.BenchmarkDigest = ""
+	data, _ := json.Marshal(manifest)
+	sum := sha256.Sum256(data)
+	return hex.EncodeToString(sum[:])
+}

