+
+func ComparePerformanceTarget(target PerformanceTarget, baseline, candidate string, qualified, blocked bool) (PerformanceComparison, error) {
+	out := PerformanceComparison{TargetID: target.ID, Baseline: baseline, Candidate: candidate}
+	if blocked {
+		out.Outcome, out.Reason = PerformanceTargetBlocked, "measurement authority is blocked"
+		return out, nil
+	}
+	if !qualified {
+		out.Outcome, out.Reason = PerformanceTargetInconclusive, "measurement did not qualify"
+		return out, nil
+	}
+	_, candidateRat, err := canonicalPerformanceDecimal(candidate)
+	if err != nil {
+		return out, fmt.Errorf("candidate: %w", err)
+	}
+	if target.Comparator == PerformanceBaseline {
+		out.ComparedValue, out.Outcome = exactPerformanceDecimal(candidateRat), PerformanceTargetBaselineRecorded
+		return out, nil
+	}
+	_, threshold, err := canonicalPerformanceDecimal(target.Value)
+	if err != nil {
+		return out, fmt.Errorf("threshold: %w", err)
+	}
+	compared := new(big.Rat).Set(candidateRat)
+	if target.Basis == PerformanceRelative {
+		_, baselineRat, parseErr := canonicalPerformanceDecimal(baseline)
+		if parseErr != nil {
+			return out, fmt.Errorf("baseline: %w", parseErr)
+		}
+		if baselineRat.Sign() == 0 {
+			out.Outcome, out.Reason = PerformanceTargetInconclusive, "baseline is zero"
+			return out, nil
+		}
+		compared.Sub(candidateRat, baselineRat)
+		compared.Mul(compared, big.NewRat(100, 1))
+		compared.Quo(compared, baselineRat)
+	}
+	out.ComparedValue = exactPerformanceDecimal(compared)
+	met := target.Comparator == PerformanceLessOrEqual && compared.Cmp(threshold) <= 0 || target.Comparator == PerformanceGreaterOrEqual && compared.Cmp(threshold) >= 0
+	if target.Gate == PerformanceReport {
+		out.Outcome = PerformanceTargetReportOnly
+	} else if met {
+		out.Outcome = PerformanceTargetMet
+	} else {
+		out.Outcome = PerformanceTargetMissed
+	}
+	return out, nil
+}
+
+func DerivePerformanceRunOutcome(outcomes []PerformanceTargetOutcome, cancelled, cleanupUncertain, blocked, stalled bool) PerformanceRunOutcome {
+	if cleanupUncertain {
+		return PerformanceCleanupUncertain
+	}
+	if cancelled {
+		return PerformanceCancelled
+	}
+	if blocked {
+		return PerformanceBlocked
+	}
+	if stalled {
+		return PerformanceStalled
+	}
+	reports := false
+	for _, outcome := range outcomes {
+		switch outcome {
+		case PerformanceTargetBlocked, PerformanceTargetInconclusive:
+			return PerformanceBlocked
+		case PerformanceTargetMissed:
+			return PerformanceTargetMiss
+		case PerformanceTargetReportOnly, PerformanceTargetBaselineRecorded:
+			reports = true
+		}
+	}
+	if reports {
+		return PerformancePassedWithReports
+	}
+	return PerformancePassed
+}
+
+func BindPerformancePacketPolicy(packet PerformanceTargetPacket, policyDigest string) PerformanceTargetPacket {
+	packet.PolicyDigest = policyDigest
+	packet.PacketDigest = performancePacketDigest(packet)
+	return packet
+}
+
+func performancePacketDigest(packet PerformanceTargetPacket) string {
+	copyPacket := packet
+	copyPacket.PacketDigest = ""
+	data, _ := json.Marshal(copyPacket)
+	sum := sha256.Sum256(data)
+	return hex.EncodeToString(sum[:])
+}
+
+func sameCells(a, b []string) bool {
+	if len(a) != len(b) {
+		return false
+	}
+	for i := range a {
+		if a[i] != b[i] {
+			return false
+		}
+	}
+	return true
+}
+
+func supportedPerformanceUnit(unit PerformanceUnit) bool {
+	switch unit {
+	case PerformanceNSPerOp, PerformanceBytesPerOp, PerformanceAllocsPerOp, PerformanceMS, PerformanceMiB, PerformanceOpsPerSec, PerformanceTasksPerRun, PerformancePercent:
+		return true
+	default:
+		return false
+	}
+}

